import random
import string


def generate_random_string(size_mb: int = 1) -> str:
    """Generate a string of random characters of the specified size in MB."""
    num_chars = size_mb * 1024 * 1024  # 1 MB = 1,048,576 characters
    characters = string.ascii_letters + string.digits + string.punctuation
    return ''.join(random.choices(characters, k=num_chars))


if __name__ == "__main__":
    result = generate_random_string(1)
    print(f"Generated string of length: {len(result)} characters ({len(result) / 1024 / 1024:.2f} MB)")
